package com.portfolio.jobhub.controller;
import com.portfolio.jobhub.model.*; import com.portfolio.jobhub.repo.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/applications") @CrossOrigin(origins="http://localhost:5173") public class ApplicationController { private final ApplicationRepository apps; private final JobRepository jobs; public ApplicationController(ApplicationRepository a,JobRepository j){apps=a;jobs=j;} @PostMapping("/jobs/{jobId}") public ResponseEntity<?> apply(@PathVariable Long jobId,@Valid @RequestBody Application a){return jobs.findById(jobId).map(j->{a.setJob(j);return ResponseEntity.status(HttpStatus.CREATED).body(apps.save(a));}).orElse(ResponseEntity.notFound().build());} @GetMapping public List<Application> all(){return apps.findAll();} @PatchMapping("/{id}/status") public ResponseEntity<Application> status(@PathVariable Long id,@RequestParam String value){return apps.findById(id).map(a->{a.setStatus(value.toUpperCase());return ResponseEntity.ok(apps.save(a));}).orElse(ResponseEntity.notFound().build());} }
